def _links(t):
    """vals[k], left[k], right[k] for the k-th real node in level order (-1 = no child)."""
    pos, c = [], 0
    for x in t:
        if x == -1:
            pos.append(-1)
        else:
            pos.append(c)
            c += 1
    vals = [x for x in t if x != -1]
    left, right = [-1] * c, [-1] * c
    for k in range(c):
        a = 2 * k + 1
        if a < len(t):
            left[k] = pos[a]
        if a + 1 < len(t):
            right[k] = pos[a + 1]
    return vals, left, right


def isSameTree(a, b):
    va, la, ra = _links(a)
    vb, lb, rb = _links(b)
    if not va or not vb:
        return not va and not vb
    stack = [(0, 0)]
    while stack:
        x, y = stack.pop()
        if x == -1 and y == -1:
            continue
        if x == -1 or y == -1 or va[x] != vb[y]:
            return False
        stack.append((la[x], lb[y]))
        stack.append((ra[x], rb[y]))
    return True
